  const modelProvider = anthropic('claude-opus-4-20250514');

    const agent = new Agent({
      model: modelProvider,
      system: 'You are a helpful AI assistant with access to web search and webpage content retrieval.',
      tools: {
        webSearch: webSearchTool,
        visitWebpage: visitWebpageTool,
      },
      stopWhen: stepCountIs(10),
    });

    console.log('Agent created successfully');
    console.log('Starting streaming...\n');
    console.log('='.repeat(50));
    console.log('Response:');
    console.log('='.repeat(50));

    const stream = agent.stream({
      messages: [
        {
          role: 'user',
          content: 'What is the capital of France? use web search',
        },
      ],
    });

    let fullText = '';
    let chunkCount = 0;

    for await (const chunk of stream.textStream) {
      chunkCount++;
      process.stdout.write(chunk);
      fullText += chunk;
    }
